def finding(item,number,refs):
    fid,name,primary,required=item; low=name.lower(); kinds=[primary,KINDS[(number+6)%len(KINDS)],KINDS[(number+13)%len(KINDS)]]
    qs=[
      {"id":f"{fid}-q01","text":f"Which stable identities, procedure classes, performed values and explicit unknowns establish {low}?","kind":kinds[0],"answer_data":["identifiers and classifications","planned and performed values","unknown and not-applicable states"]},
      {"id":f"{fid}-q02","text":f"Who requested, authorized, performed, assisted, recorded or reported {low}, using which evidence, competence and delegated authority?","kind":kinds[1],"answer_data":["participants and roles","evidence and competence","authority and limitations"]},
      {"id":f"{fid}-q03","text":f"Which scheduled, occurrence, performer, recorded, reported and knowledge times apply to {low}, and how may it be validated, challenged, corrected or retained?","kind":kinds[2],"answer_data":["distinct event and record times","validation and challenge","successor correction and retention"]}]
    return {"id":fid,"name":name,"description":f"Records {low} as source-qualified procedure-occurrence context while preserving external clinical masters and the separation among request, performance, result, report and adverse event.","source_refs":refs,"questions":qs,"data_elements":[{"id":f"{fid}-data","name":f"{name} data","description":f"Typed procedure-occurrence data for {low} with source, authority, event time, status, evidence and provenance.","value_kind":"collection","cardinality":"1" if required else "0..n","required":required,"source_refs":refs}],"artifacts":[{"id":f"{fid}-record","name":f"{name} record","description":f"Immutable or successor-versioned evidence-bearing procedure record for {low}.","media_or_form":["logical procedure assertion","request binding, safety check, event, outcome, evidence or projection record"],"serial":True,"identity_strategy":f"Procedure occurrence ID plus {fid} assertion or event ID; patient, code, date, encounter and billing claim never identify the occurrence alone.","source_refs":refs}],"inline_only_rationale":None}

def structure():
    out=[]; n=0
    for bid,bname,rat,layers in ROWS:
        rendered=[]
        for lid,lname,refs,items in layers:
            vals=[]
            for item in items: n+=1; vals.append(finding(item,n,refs))
            rendered.append({"id":lid,"name":lname,"description":f"Groups source-qualified procedure context for {lname.lower()}.","source_refs":refs,"findings":vals})
        out.append({"id":bid,"name":bname,"description":f"Groups governed procedure-occurrence context for {bname.lower()}.","rationale":rat+".","source_refs":sorted({r for layer in layers for r in layer[2]}),"layers":rendered})
    return {"bundles":out}

